    actual:=actual||RTRIM(r.text,CHR(13)||CHR(10)||'' '')||CHR(10);
   END IF;
  END LOOP;
  require(DBMS_LOB.COMPARE(actual,p_expected)=0,''Installed source differs: ''||p_name||'' ''||p_type);
